def solve(s):
    s = ''.join(c for c in s if c.isalnum()).lower()
    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1
    return True

def parse_interests(input_string):
    """
    Parses a comma-separated string of interests and returns a dictionary 
    mapping each interest to its frequency.
    """
    if not input_string:
        return {}

    # Split by comma, strip whitespace from each tag, and filter out empty strings
    tags = [tag.strip() for tag in input_string.split(',') if tag.strip()]

    frequency_map = {}
    for tag in tags:
        frequency_map[tag] = frequency_map.get(tag, 0) + 1

    return frequency_map

