def extract_sensors(data_str: str) -> set[str]:
    """
    Extracts the unique identifiers of sensors that are malfunctioning from a given string.

    Args:
        data_str (str): A string in the format 'sensor_id:status,sensor_id2:status,...'

    Returns:
        set[str]: A set containing the IDs of all malfunctioning sensors.
    """
    if not data_str:
        return set()

    malfunctioning_sensors = set()
    # Split the string into individual sensor-status pairs
    entries = data_str.split(',')

    for entry in entries:
        # Ensure the entry contains a colon to separate ID and status
        if ':' in entry:
            sensor_id, status = entry.split(':', 1)
            # Check if the status is 'malfunctioning'
            if status.strip().lower() == 'malfunctioning':
                malfunctioning_sensors.add(sensor_id.strip())

    return malfunctioning_sensors

