def count_domain_frequencies(domain_features):
    """
    Aggregates feature counts across all domains.

    Args:
        domain_features (dict): A dictionary where keys are domain names and 
                                values are dictionaries of feature counts.

    Returns:
        dict: A dictionary where each key is a unique feature name and its 
              value is the total count across all domains.
    """
    frequency_counts = {}

    # Iterate through each domain's features
    for features in domain_features.values():
        # Iterate through each feature and its associated count in the current domain
        for feature, count in features.items():
            # Update the total frequency counts using .get() to handle new keys
            frequency_counts[feature] = frequency_counts.get(feature, 0) + count

    return frequency_counts

