def find_smallest_index(lst):
    """
    Finds the index of the smallest element in a list.
    If there are multiple smallest elements, returns the first one from the left.
    Works for sorted (ascending, descending) and unsorted lists.
    """
    if not lst:
        return None

    min_idx = 0
    for i in range(1, len(lst)):
        if lst[i] < lst[min_idx]:
            min_idx = i

    return min_idx

