def find_first_occurrence(numbers, target):
    """
    Finds the index of the first occurrence of a target integer in a list of integers.

    Args:
        numbers (list[int]): A list of integers to search through.
        target (int): The integer value to locate.

    Returns:
        int: The index of the first occurrence of target in numbers.

    Raises:
        ValueError: If the target is not found in the numbers list.
        TypeError: If numbers is not a list or target is not an integer.
    """
    # Validate input types to ensure robustness
    if not isinstance(numbers, list):
        raise TypeError(f"Expected 'numbers' to be a list, but got {type(numbers).__name__}.")

    if not isinstance(target, int):
        raise TypeError(f"Expected 'target' to be an integer, but got {type(target).__name__}.")

    # Iterate through the list with enumerate to track both index and value
    for index, value in enumerate(numbers):
        # Check if the current element matches the target
        if value == target:
            return index

    # If the loop completes without returning, the target was not found
    raise ValueError(f"The target value {target} was not found in the provided list.")

