def find_max_depth(tree: dict) -> int:
    """
    Calculates the maximum depth of a tree (or forest) represented as an adjacency list.
    The root node is at level 0.

    Args:
        tree (dict): A dictionary where each key is a node and its value is a list of children.

    Returns:
        int: The maximum depth of the tree.
    """
    if not tree:
        return 0

    # Step 1: Identify all unique nodes in the graph (keys and all children)
    all_nodes = set(tree.keys())
    for children in tree.values():
        all_nodes.update(children)

    if not all_nodes:
        return 0

    # Step 2: Calculate in-degrees to find the roots (nodes with no parents)
    in_degree = {node: 0 for node in all_nodes}
    for parent, children in tree.items():
        for child in children:
            in_degree[child] += 1

    # A root is a node that has no incoming edges.
    roots = [node for node in all_nodes if in_degree[node] == 0]

    # If no roots are found but nodes exist, the graph contains a cycle (not a tree).
    if not roots:
        return 0

    # Step 3: Use Memoization (Dynamic Programming) to prevent redundant computations.
    memo = {}

    def get_depth(u):
        """Recursive helper function to find depth of node u."""
        if u in memo:
            return memo[u]

        children = tree.get(u, [])
        if not children:
            # Base case: A leaf node has a depth of 0 relative to itself.
            res = 0
        else:
            # Recursive step: Depth is 1 + the maximum depth among its children.
            res = 1 + max(get_depth(v) for v in children)

        memo[u] = res
        return res

    # Step 4: Calculate the maximum depth starting from all identified roots.
    # This handles both a single tree and a forest of multiple trees.
    return max(get_depth(root) for root in roots)

